async ({ workspace: { read, edit, batch } }) => {
  const pkg = await read("package.json", { format: "raw" });
  const lock = await read("package-lock.json", { format: "raw" });
  const p = pkg.content.replace('"version": "0.38.0"', '"version": "0.38.1"');
  // lock: first two occurrences (root and packages[""])
  let n = 0;
  const l = lock.content.replace(/"version": "0\.38\.0"/g, (m) => (n++ < 2 ? '"version": "0.38.1"' : m));
  const entry = "## [0.38.1] - 2026-11-17\n\n### Fixed\n\n- `typescript` calls that set their label or other options in a `// @pit: {...}` source header show that label and those inputs in the call's header and expanded view, as they do when the options are passed as tool arguments. A streaming, malformed, or conflicting header still renders the call as written.\n";
  return batch([
    { kind: "edit", file: "package.json", changes: { revision: pkg.revision, changes: [{ kind: "replaceFile", content: p }] } },
    { kind: "edit", file: "package-lock.json", changes: { revision: lock.revision, changes: [{ kind: "replaceFile", content: l }] } },
    { kind: "edit", file: "CHANGELOG.md", changes: { revision: "71_ASGk-2Lu8", changes: [{ kind: "insertAfter", anchor: "6:47DEQ", content: entry }] } },
    { kind: "edit", file: "README.md", changes: { revision: "jjnLXhBtKI43", changes: [{ kind: "replace", start: "53:IeQby", content: "Run `/reload` after updating. Prefer a fixed release? Use `pi install git:github.com/cv/pit@v0.38.1` instead; package updates won't move a pinned install." }] } },
  ]).then(async (r) => ({ n, diff: null, ok: r.results.map((x: any) => x.ok ?? x.status ?? "?") }));
}
